import React from "react";
import {
  FaChevronLeft,
  FaPaperPlane,
  FaMicrophone,
  FaStop,
  FaTrash,
  FaPlay,
  FaPause,
} from "react-icons/fa";
import { apiGet } from "../common/api";
import Loader from "../common/Loader";
import withRouter from "../common/withRouter";

const API_URL = "https://iranaserviceapp.ir/test/api";

class VoicePlayer extends React.Component {
  constructor(props) {
    super(props);

    this.state = {
      playing: false,
      currentTime: 0,
      duration: 0,
    };

    this.audio = null;
    this.handlePlayPause = this.handlePlayPause.bind(this);
    this.handleTimeUpdate = this.handleTimeUpdate.bind(this);
    this.handleLoadedMetadata =
      this.handleLoadedMetadata.bind(this);
    this.handleEnded = this.handleEnded.bind(this);
    this.handleSeek = this.handleSeek.bind(this);
  }

  componentWillUnmount() {
    if (this.audio) {
      this.audio.pause();
    }
  }

  handlePlayPause() {
    if (!this.audio) {
      return;
    }

    if (this.audio.paused) {
      this.audio.play().catch((error) => {
        console.error("AUDIO PLAY ERROR:", error);
      });
    } else {
      this.audio.pause();
    }
  }

  handleTimeUpdate() {
    if (!this.audio) {
      return;
    }

    this.setState({
      currentTime: this.audio.currentTime,
    });
  }

  handleLoadedMetadata() {
    if (!this.audio) {
      return;
    }

    this.setState({
      duration: this.audio.duration || 0,
    });
  }

  handleEnded() {
    this.setState({
      playing: false,
      currentTime: 0,
    });

    if (this.audio) {
      this.audio.currentTime = 0;
    }
  }

  handleSeek(e) {
    if (!this.audio || !this.state.duration) {
      return;
    }

    const value = Number(e.target.value);

    this.audio.currentTime = value;

    this.setState({
      currentTime: value,
    });
  }

  formatTime(seconds) {
    if (!seconds || isNaN(seconds)) {
      return "0:00";
    }

    const minutes = Math.floor(seconds / 60);
    const remainingSeconds = Math.floor(seconds % 60);

    return `${minutes}:${String(
      remainingSeconds
    ).padStart(2, "0")}`;
  }

  renderWave() {
    const bars = [
      7, 12, 18, 10, 15, 22, 13, 8, 19, 25, 14, 10, 20, 16,
      9, 14, 23, 12, 18, 8, 15, 21, 11, 17, 9, 20, 14, 24,
      10, 16, 8, 19, 13, 22, 11, 17, 9, 15, 23, 12, 18, 10,
      20, 14, 8, 16, 22, 11, 19, 13, 24, 9, 17, 12, 21, 15,
    ];

    const { currentTime, duration } = this.state;

    const progress =
      duration > 0
        ? (currentTime / duration) * 100
        : 0;

    return (
      <div
        className="d-flex align-items-center gap-1 flex-grow-1"
        style={{
          height: 34,
          overflow: "hidden",
        }}
      >
        {bars.map((height, index) => {
          const position =
            (index / bars.length) * 100;

          const active = position <= progress;

          return (
            <div
              key={index}
              style={{
                width: 3,
                height,
                minHeight: 5,
                borderRadius: 3,
                backgroundColor: active
                  ? "#0d6efd"
                  : "#adb5bd",
                transition:
                  "background-color 0.1s linear",
                flexShrink: 0,
              }}
            />
          );
        })}
      </div>
    );
  }

  render() {
    const {
      playing,
      currentTime,
      duration,
    } = this.state;

    return (
      <div
        className="d-flex align-items-center"
        style={{
          width: "100%",
          minWidth: 230,
          maxWidth: 290,
          gap: 10,
        }}
      >
        <audio
          ref={(audio) => {
            this.audio = audio;
          }}
          src={this.props.src}
          preload="metadata"
          onPlay={() =>
            this.setState({
              playing: true,
            })
          }
          onPause={() =>
            this.setState({
              playing: false,
            })
          }
          onTimeUpdate={this.handleTimeUpdate}
          onLoadedMetadata={
            this.handleLoadedMetadata
          }
          onEnded={this.handleEnded}
          style={{
            display: "none",
          }}
        />

        <button
          type="button"
          onClick={this.handlePlayPause}
          className="border-0 rounded-circle d-flex align-items-center justify-content-center"
          style={{
            width: 42,
            height: 42,
            minWidth: 42,
            backgroundColor: "#0d6efd",
            color: "#fff",
            cursor: "pointer",
          }}
        >
          {playing ? (
            <FaPause size={14} />
          ) : (
            <FaPlay
              size={14}
              style={{
                marginRight: -2,
              }}
            />
          )}
        </button>

        <div
          className="d-flex flex-column flex-grow-1"
          style={{
            minWidth: 0,
          }}
        >
          <input
            type="range"
            min="0"
            max={duration || 0}
            step="0.01"
            value={currentTime}
            onChange={this.handleSeek}
            style={{
              position: "absolute",
              opacity: 0,
              pointerEvents: "none",
              width: 1,
              height: 1,
            }}
          />

          <div
            className="d-flex align-items-center"
            style={{
              cursor: "pointer",
            }}
            onClick={(e) => {
              if (!this.audio || !duration) {
                return;
              }

              const rect =
                e.currentTarget.getBoundingClientRect();

              const x =
                e.clientX - rect.left;

              const percentage =
                Math.max(
                  0,
                  Math.min(
                    1,
                    x / rect.width
                  )
                );

              const newTime =
                percentage * duration;

              this.audio.currentTime =
                newTime;

              this.setState({
                currentTime: newTime,
              });
            }}
          >
            {this.renderWave()}
          </div>

          <div
            className="d-flex justify-content-between align-items-center"
            style={{
              marginTop: 1,
            }}
          >
            <span
              className="text-muted"
              style={{
                fontSize: 11,
              }}
            >
              {this.formatTime(currentTime)}
            </span>

            <span
              className="text-muted"
              style={{
                fontSize: 11,
              }}
            >
              {this.formatTime(duration)}
            </span>
          </div>
        </div>
      </div>
    );
  }
}

class ChatSupportPage extends React.Component {
  constructor(props) {
    super(props);

    this.state = {
      messages: [],
      text: "",
      loading: true,
      sending: false,
      recording: false,
      audioUrl: null,
      recordingTime: 0,
    };

    this.mediaRecorder = null;
    this.audioChunks = [];
    this.audioStream = null;
    this.audioBlob = null;
    this.timer = null;

    this.handleBack = this.handleBack.bind(this);
    this.handleTextChange =
      this.handleTextChange.bind(this);
    this.handleSend = this.handleSend.bind(this);
    this.startRecording =
      this.startRecording.bind(this);
    this.stopRecording =
      this.stopRecording.bind(this);
    this.cancelRecording =
      this.cancelRecording.bind(this);
    this.sendVoice =
      this.sendVoice.bind(this);
  }

  componentDidMount() {
    this.loadMessages();
  }

  componentWillUnmount() {
    this.stopTimer();

    if (this.audioStream) {
      this.audioStream
        .getTracks()
        .forEach((track) => {
          track.stop();
        });
    }

    if (this.state.audioUrl) {
      URL.revokeObjectURL(
        this.state.audioUrl
      );
    }
  }

  loadMessages() {
    apiGet("/messages")
      .then((json) => {
        this.setState({
          messages: json.messages || [],
          loading: false,
        });
      })
      .catch((error) => {
        console.error(
          "MESSAGES ERROR:",
          error
        );

        this.setState({
          loading: false,
        });
      });
  }

  handleBack() {
    this.props.navigate(-1);
  }

  handleTextChange(e) {
    this.setState({
      text: e.target.value,
    });
  }

  handleSend(e) {
    e.preventDefault();

    const { text } = this.state;

    if (!text.trim()) {
      return;
    }

    const token =
      localStorage.getItem("token");

    this.setState({
      sending: true,
    });

    fetch(`${API_URL}/messages`, {
      method: "POST",

      headers: {
        "Content-Type":
          "application/json",
        Accept: "application/json",
        Authorization: `Bearer ${token}`,
      },

      body: JSON.stringify({
        text: text.trim(),
      }),
    })
      .then((response) =>
        response.json()
      )
      .then((data) => {
        console.log(
          "SEND MESSAGE:",
          data
        );

        if (data.status !== "1") {
          throw new Error(
            data.message ||
              "ارسال پیام انجام نشد."
          );
        }

        this.setState({
          sending: false,
          text: "",
        });

        this.loadMessages();
      })
      .catch((error) => {
        console.error(
          "SEND MESSAGE ERROR:",
          error
        );

        this.setState({
          sending: false,
        });
      });
  }

  async startRecording() {
    try {
      if (
        !navigator.mediaDevices ||
        !navigator.mediaDevices
          .getUserMedia
      ) {
        alert(
          "مرورگر شما از ضبط صدا پشتیبانی نمی‌کند."
        );

        return;
      }

      const stream =
        await navigator.mediaDevices.getUserMedia(
          {
            audio: true,
          }
        );

      this.audioStream = stream;
      this.audioChunks = [];
      this.audioBlob = null;

      let mimeType = "audio/webm";

      if (
        !MediaRecorder.isTypeSupported(
          "audio/webm"
        )
      ) {
        if (
          MediaRecorder.isTypeSupported(
            "audio/mp4"
          )
        ) {
          mimeType = "audio/mp4";
        } else if (
          MediaRecorder.isTypeSupported(
            "audio/ogg"
          )
        ) {
          mimeType = "audio/ogg";
        } else {
          mimeType = "";
        }
      }

      this.mediaRecorder = mimeType
        ? new MediaRecorder(stream, {
            mimeType,
          })
        : new MediaRecorder(stream);

      this.mediaRecorder.ondataavailable =
        (event) => {
          if (
            event.data &&
            event.data.size > 0
          ) {
            this.audioChunks.push(
              event.data
            );
          }
        };

      this.mediaRecorder.onstop = () => {
        const actualMimeType =
          this.mediaRecorder.mimeType ||
          mimeType ||
          "audio/webm";

        const audioBlob = new Blob(
          this.audioChunks,
          {
            type: actualMimeType,
          }
        );

        const audioUrl =
          URL.createObjectURL(
            audioBlob
          );

        this.audioBlob = audioBlob;

        this.setState({
          recording: false,
          audioUrl,
          recordingTime: 0,
        });

        if (this.audioStream) {
          this.audioStream
            .getTracks()
            .forEach((track) =>
              track.stop()
            );

          this.audioStream = null;
        }

        this.stopTimer();
      };

      this.mediaRecorder.start();

      this.setState({
        recording: true,
        recordingTime: 0,
        audioUrl: null,
      });

      this.startTimer();
    } catch (error) {
      console.error(
        "RECORDING ERROR:",
        error
      );

      alert(
        "دسترسی به میکروفون داده نشد. لطفاً اجازه استفاده از میکروفون را فعال کنید."
      );
    }
  }

  stopRecording() {
    if (
      this.mediaRecorder &&
      this.mediaRecorder.state !==
        "inactive"
    ) {
      this.mediaRecorder.stop();
    }
  }

  cancelRecording() {
    if (
      this.mediaRecorder &&
      this.mediaRecorder.state !==
        "inactive"
    ) {
      this.mediaRecorder.ondataavailable =
        null;

      this.mediaRecorder.onstop = null;

      this.mediaRecorder.stop();
    }

    if (this.audioStream) {
      this.audioStream
        .getTracks()
        .forEach((track) =>
          track.stop()
        );

      this.audioStream = null;
    }

    this.stopTimer();

    if (this.state.audioUrl) {
      URL.revokeObjectURL(
        this.state.audioUrl
      );
    }

    this.audioChunks = [];
    this.audioBlob = null;

    this.setState({
      recording: false,
      audioUrl: null,
      recordingTime: 0,
    });
  }

  startTimer() {
    this.stopTimer();

    this.timer = setInterval(() => {
      this.setState(
        (prevState) => ({
          recordingTime:
            prevState.recordingTime + 1,
        })
      );
    }, 1000);
  }

  stopTimer() {
    if (this.timer) {
      clearInterval(this.timer);
      this.timer = null;
    }
  }

  formatTime(seconds) {
    const minutes = Math.floor(
      seconds / 60
    );

    const remainingSeconds =
      seconds % 60;

    return `${String(minutes).padStart(
      2,
      "0"
    )}:${String(
      remainingSeconds
    ).padStart(2, "0")}`;
  }

  sendVoice() {
    if (!this.audioBlob) {
      return;
    }

    const token =
      localStorage.getItem("token");

    this.setState({
      sending: true,
    });

    const formData =
      new FormData();

    let extension = "webm";

    if (
      this.audioBlob.type.includes(
        "mp4"
      )
    ) {
      extension = "mp4";
    } else if (
      this.audioBlob.type.includes(
        "ogg"
      )
    ) {
      extension = "ogg";
    }

    const fileName = `voice_${Date.now()}.${extension}`;

    formData.append(
      "file",
      this.audioBlob,
      fileName
    );

    formData.append("text", "");
    formData.append("hash", "");
    formData.append(
      "size",
      this.audioBlob.size
    );

    console.log("VOICE FILE:", {
      name: fileName,
      type: this.audioBlob.type,
      size: this.audioBlob.size,
    });

    fetch(`${API_URL}/messages`, {
      method: "POST",

      headers: {
        Accept: "application/json",
        Authorization: `Bearer ${token}`,
      },

      body: formData,
    })
      .then((response) =>
        response.json()
      )
      .then((data) => {
        console.log(
          "SEND VOICE:",
          data
        );

        if (data.status !== "1") {
          throw new Error(
            data.message ||
              "ارسال ویس انجام نشد."
          );
        }

        if (this.state.audioUrl) {
          URL.revokeObjectURL(
            this.state.audioUrl
          );
        }

        this.audioBlob = null;

        this.setState({
          sending: false,
          audioUrl: null,
          recordingTime: 0,
        });

        this.loadMessages();
      })
      .catch((error) => {
        console.error(
          "SEND VOICE ERROR:",
          error
        );

        this.setState({
          sending: false,
        });

        alert(
          "ارسال ویس انجام نشد."
        );
      });
  }

  getFileUrl(file) {
    if (!file) {
      return "";
    }

    if (
      file.startsWith("http://") ||
      file.startsWith("https://")
    ) {
      return file;
    }

    return `${API_URL.replace(
      "/api",
      ""
    )}/files/chats${file}`;
  }

  renderMessage(message) {
    const hasFile = !!message.file;
    const hasText = !!message.text;

    return (
      <div
        key={message.id}
        className="mb-3 text-end"
      >
        <div
          className="d-inline-flex flex-column align-items-end bg-light rounded-3 px-3 py-2"
          style={{
            maxWidth: "85%",
            minWidth: hasFile
              ? 260
              : "auto",
          }}
        >
          {hasFile && (
            <VoicePlayer
              src={this.getFileUrl(
                message.file
              )}
            />
          )}

          {hasText && (
            <div
              className="text-dark mt-1"
              style={{
                wordBreak: "break-word",
              }}
            >
              {message.text}
            </div>
          )}
        </div>
      </div>
    );
  }

  render() {
    const {
      messages,
      text,
      loading,
      sending,
      recording,
      audioUrl,
      recordingTime,
    } = this.state;

    return (
      <div
        dir="rtl"
        lang="fa"
        className="bg-white min-vh-100 d-flex flex-column"
      >
        {loading && <Loader />}

        <div
          className="d-flex align-items-center justify-content-between px-3 pt-4 pb-3 border-bottom"
          style={{
            maxWidth: 480,
            margin: "0 auto",
            width: "100%",
          }}
        >
          <button
            type="button"
            onClick={this.handleBack}
            className="btn btn-light rounded-circle border p-2 d-flex align-items-center justify-content-center"
            style={{
              width: 36,
              height: 36,
            }}
          >
            <FaChevronLeft size={14} />
          </button>

          <h1 className="fs-6 fw-semibold text-dark m-0">
            پشتیبانی
          </h1>

          <div
            style={{
              width: 36,
            }}
          />
        </div>

        <div
          className="flex-grow-1 px-3 py-3 overflow-auto"
          style={{
            maxWidth: 480,
            margin: "0 auto",
            width: "100%",
          }}
        >
          {messages.length === 0 &&
          !loading ? (
            <div className="text-center text-muted py-5">
              هنوز پیامی وجود ندارد.
            </div>
          ) : (
            messages.map((message) =>
              this.renderMessage(
                message
              )
            )
          )}
        </div>

        {audioUrl && !recording && (
          <div
            className="px-3 pb-2"
            style={{
              maxWidth: 480,
              margin: "0 auto",
              width: "100%",
            }}
          >
            <div
              className="border rounded-4 p-2 d-flex align-items-center gap-2"
              style={{
                backgroundColor:
                  "#f8f9fa",
              }}
            >
              <div
                className="flex-grow-1"
                style={{
                  minWidth: 0,
                }}
              >
                <VoicePlayer
                  src={audioUrl}
                />
              </div>

              <button
                type="button"
                onClick={
                  this.cancelRecording
                }
                disabled={sending}
                className="btn btn-light text-danger rounded-circle d-flex align-items-center justify-content-center"
                style={{
                  width: 40,
                  height: 40,
                  flexShrink: 0,
                }}
              >
                <FaTrash size={14} />
              </button>

              <button
                type="button"
                onClick={this.sendVoice}
                disabled={sending}
                className="btn btn-primary rounded-circle d-flex align-items-center justify-content-center"
                style={{
                  width: 40,
                  height: 40,
                  flexShrink: 0,
                }}
              >
                <FaPaperPlane size={14} />
              </button>
            </div>
          </div>
        )}

        {!recording && !audioUrl && (
          <form
            onSubmit={this.handleSend}
            className="d-flex align-items-center gap-2 px-3 py-3 border-top"
            style={{
              maxWidth: 480,
              margin: "0 auto",
              width: "100%",
            }}
          >
            <button
              type="button"
              onClick={
                this.startRecording
              }
              disabled={sending}
              className="btn btn-light border rounded-circle p-2 d-flex align-items-center justify-content-center"
              style={{
                width: 40,
                height: 40,
                flexShrink: 0,
              }}
            >
              <FaMicrophone size={16} />
            </button>

            <input
              type="text"
              placeholder="پیام خود را بنویسید..."
              value={text}
              onChange={
                this.handleTextChange
              }
              className="form-control border rounded-pill text-end px-3 py-2"
            />

            <button
              type="submit"
              disabled={
                sending ||
                !text.trim()
              }
              className="btn btn-primary rounded-circle p-2 d-flex align-items-center justify-content-center"
              style={{
                width: 40,
                height: 40,
                flexShrink: 0,
              }}
            >
              <FaPaperPlane size={14} />
            </button>
          </form>
        )}

        {recording && (
          <div
            className="px-3 py-3 border-top"
            style={{
              maxWidth: 480,
              margin: "0 auto",
              width: "100%",
            }}
          >
            <div className="d-flex align-items-center gap-2">
              <button
                type="button"
                onClick={
                  this.cancelRecording
                }
                className="btn btn-light text-danger border rounded-circle d-flex align-items-center justify-content-center"
                style={{
                  width: 40,
                  height: 40,
                  flexShrink: 0,
                }}
              >
                <FaTrash size={14} />
              </button>

              <div className="flex-grow-1 bg-light rounded-pill px-3 py-2 d-flex align-items-center justify-content-between">
                <span className="text-danger fw-semibold">
                  ● در حال ضبط
                </span>

                <span className="text-dark">
                  {this.formatTime(
                    recordingTime
                  )}
                </span>
              </div>

              <button
                type="button"
                onClick={
                  this.stopRecording
                }
                className="btn btn-danger rounded-circle d-flex align-items-center justify-content-center"
                style={{
                  width: 40,
                  height: 40,
                  flexShrink: 0,
                }}
              >
                <FaStop size={14} />
              </button>
            </div>
          </div>
        )}
      </div>
    );
  }
}

export default withRouter(
  ChatSupportPage
);
